import ast,copy,hashlib,json
from pathlib import Path
base=ast.parse(Path('history_g2_r0034_joint_dice_both.py').read_text())
files=['joint_batch_reference.py','joint_batch_affine.py','joint_batch_dice.py','candidate.py']
def methods(tree):
 return {n.name:n for c in tree.body if isinstance(c,ast.ClassDef) and c.name=='Model' for n in c.body if isinstance(n,ast.FunctionDef)}
def dump(n):return ast.dump(n,include_attributes=False)
bm=methods(base)
for fn in files:
 raw=Path(fn).read_bytes();t=ast.parse(raw,filename=fn);compile(t,fn,'exec')
 config=ast.literal_eval(next(n.value for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets)))
 m=methods(t)
 if fn=='joint_batch_reference.py':
  assert raw==Path('history_g2_r0034_joint_dice_both.py').read_bytes()
 else:
  for name,node in bm.items():
   if name not in ('__init__','forward'):assert dump(node)==dump(m[name]),(fn,name)
  assert not any(isinstance(n,(ast.Import,ast.ImportFrom)) and any(a.name not in ('torch','torch.nn','unirank.pytorch.models','unirank.pytorch.layers','unirank.pytorch.layers.activations') for a in ([ast.alias(n.module)] if isinstance(n,ast.ImportFrom) else n.names)) for n in t.body)
  # Removing the explicitly evaluation-only dispatch and a Python list must
  # recover the exact inherited forward AST, including all training operations.
  forward=copy.deepcopy(m['forward'])
  class StripDispatch(ast.NodeTransformer):
   def visit_Assign(self,n):
    if any(isinstance(x,ast.Name) and x.id=='task_features' for x in n.targets):return None
    return self.generic_visit(n)
   def visit_If(self,n):
    if 'evaluation_tower_batching' in ast.unparse(n.test):return None
    return self.generic_visit(n)
  forward=StripDispatch().visit(forward)
  assert dump(forward)==dump(bm['forward']),(fn,'forward changed beyond declared dispatch')
  ctor=copy.deepcopy(m['__init__'])
  argidx=next(i for i,a in enumerate(ctor.args.args) if a.arg=='evaluation_tower_batching')
  defaultidx=argidx-(len(ctor.args.args)-len(ctor.args.defaults))
  del ctor.args.args[argidx];del ctor.args.defaults[defaultidx]
  class StripConfig(ast.NodeTransformer):
   def visit_Assign(self,n):
    if any(isinstance(x,ast.Attribute) and x.attr=='evaluation_tower_batching' for x in n.targets):return None
    return self.generic_visit(n)
   def visit_If(self,n):
    code=ast.unparse(n.test)
    if 'evaluation_tower_batching' in code or code==\"evaluation_dice "'!= '"'both'\":return None
    return self.generic_visit(n)
  ctor=StripConfig().visit(ctor)
  assert dump(ctor)==dump(bm['__init__']),(fn,'constructor changed beyond config checks')
  assert not any(isinstance(n,ast.FunctionDef) and n.name=='training_loss' for n in ast.walk(t))
 print(fn,hashlib.sha256(raw).hexdigest(),config.get('evaluation_tower_batching','inherited serial'), 'syntax/source invariants PASS')
print('No model imports, tensor execution, training, installations or scoring were performed.')
